pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 val, address log) internal {
        try c.Initialized() {} catch { return; }
        bool r1;
        bool r2;
        try c.SetMinSum(val) { r1 = false; } catch { r1 = true; }
        try c.SetLogFile(log) { r2 = false; } catch { r2 = true; }
        assertTrue(r1 && r2);
    }

    function testFuzz_run(uint256 val, address log) public {
        vm.assume(log.code.length == 0 && uint160(log) > 0xffff && log != address(this) && log != address(c) && log != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && log != 0x000000000000000000636F6e736F6c652e6c6f67 && log != 0x4e59b44847b379578588920cA78FbF26c0B4956C && log != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(val, log);
    }

    receive() external payable {}
}
